export function LetterSpacing({
  spacing = {{spacing}},
  text = "{{text}}",
  uppercase = {{uppercase}},
  size = {{size}},
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <p style={{ margin: 0, fontWeight: 700, letterSpacing: spacing, fontSize: size, textTransform: uppercase ? "uppercase" : "none" }}>{text}</p>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>letter-spacing: {spacing}px</p>
    </div>
  );
}
